// Shared by every Code node. scripts/build.mjs pastes this file in front of
// route.js, render.js and notify.js, because n8n Code nodes cannot import.

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Everything that came from a person or the database goes through esc()
// before it is put into a message, because messages are sent as HTML.
const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

// Days travel as "2026-11-14" in data and as "20261114" inside buttons. They
// are plain calendar dates in the studio's time zone; Postgres owns the clock.
const asDate = (iso) => new Date(`${iso}T00:00:00Z`);
const addDays = (iso, count) => {
  const date = asDate(iso);
  date.setUTCDate(date.getUTCDate() + count);
  return date.toISOString().slice(0, 10);
};
const dayName = (iso) => {
  const date = asDate(iso);
  return `${WEEKDAYS[date.getUTCDay()]} ${date.getUTCDate()} ${MONTHS[date.getUTCMonth()]}`;
};
const dayLabel = (iso, today) => {
  if (iso === today) return `${dayName(iso)} (today)`;
  if (iso === addDays(today, 1)) return `${dayName(iso)} (tomorrow)`;
  return dayName(iso);
};
const packDay = (iso) => iso.replace(/-/g, '');
const unpackDay = (packed) => {
  if (!/^\d{8}$/.test(packed ?? '')) return null;
  const iso = `${packed.slice(0, 4)}-${packed.slice(4, 6)}-${packed.slice(6, 8)}`;
  const date = asDate(iso);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === iso ? iso : null;
};
const packTime = (hhmm) => hhmm.replace(':', '');
const unpackTime = (packed) => {
  if (!/^\d{4}$/.test(packed ?? '')) return null;
  const hours = Number(packed.slice(0, 2));
  const minutes = Number(packed.slice(2, 4));
  return hours < 24 && minutes < 60 ? `${packed.slice(0, 2)}:${packed.slice(2, 4)}` : null;
};

const button = (text, data) => ({ text, callback_data: data });
const rowsOf = (items, perRow) => {
  const rows = [];
  for (let i = 0; i < items.length; i += perRow) rows.push(items.slice(i, i + perRow));
  return rows;
};

// A booking or a move in progress is not stored anywhere. Each button carries
// every choice made so far, for example "b:c2:r1:d20261114:t0900":
//   c class type   r room (0 = ask)   d day   t start time
//   p trainer (0 = ask)   n weeks to repeat   w week shown in the day picker
// So there is no session to expire or to get out of step with the screen, and
// "Back" is simply the same data with the last choice left out. Telegram
// allows 64 bytes per button; the longest of these is under 50.
const STEP_KEYS = ['c', 'r', 'd', 't', 'p', 'n', 'w'];
const wizard = (base, steps) =>
  [base]
    .concat(
      STEP_KEYS.filter((key) => steps[key] !== undefined && steps[key] !== null).map(
        (key) => `${key}${steps[key]}`,
      ),
    )
    .join(':');
const without = (steps, ...keys) =>
  Object.fromEntries(Object.entries(steps).filter(([key]) => !keys.includes(key)));
const readSteps = (parts) => {
  const steps = {};
  for (const part of parts) {
    const key = part[0];
    const value = part.slice(1);
    if (!STEP_KEYS.includes(key)) continue;
    if (key === 'd' && unpackDay(value)) steps.d = value;
    else if (key === 't' && unpackTime(value)) steps.t = value;
    else if ('crpnw'.includes(key) && /^\d{1,9}$/.test(value)) steps[key] = String(Number(value));
  }
  return steps;
};
// The "Write notifications" Code node: turn rows of studio.outbox into
// messages. These go to people who did not tap anything: a trainer whose class
// an admin moved, the admins when someone asks for access, reminders.

function classLines(b, today) {
  return [
    `<b>${esc(b.class)}</b> · ${b.minutes} min`,
    `Room: ${esc(b.room)}`,
    `When: ${dayLabel(b.day, today)}, ${b.from}–${b.to}`,
    `Trainer: ${esc(b.trainer)}`,
  ].join('\n');
}

function leadTime(minutes) {
  if (minutes === 1440) return 'Tomorrow at this time';
  if (minutes > 1440 && minutes % 1440 === 0) return `In ${minutes / 1440} days`;
  if (minutes >= 60 && minutes % 60 === 0) return minutes === 60 ? 'In 1 hour' : `In ${minutes / 60} hours`;
  return `In ${minutes} minutes`;
}

const NOTIFICATIONS = {
  access_request(p) {
    return {
      text: `<b>${esc(p.name)}</b>${p.username ? ` (@${esc(p.username)})` : ''} wants to use the studio bot.`,
      rows: [[button('Review', `pv:${p.person_id}`)]],
    };
  },

  access_granted(p, ctx) {
    const role = p.role === 'admin' ? 'an admin' : 'a trainer';
    return {
      text: p.first_time
        ? `You are in. You can now use the <b>${esc(ctx.studio.name)}</b> bot as ${role}.`
        : `Your role at <b>${esc(ctx.studio.name)}</b> changed: you are now ${role}.`,
      rows: [[button('Open the menu', 'h')]],
    };
  },

  booked(p, ctx) {
    const who = p.yours ? `${esc(p.actor)} booked you for` : `${esc(p.actor)} booked`;
    const what = p.count > 1 ? `${p.count} weekly classes, starting with:` : 'a class:';
    return {
      text: `${who} ${what}\n\n${classLines(p.booking, ctx.today)}`,
      rows: [[button('Open class', `v:${p.booking.id}`)]],
    };
  },

  moved(p, ctx) {
    return {
      text: [
        `${esc(p.actor)} moved ${p.yours ? 'your class' : 'a class'}.`,
        '',
        classLines(p.booking, ctx.today),
        '',
        `Was: ${dayLabel(p.was.day, ctx.today)}, ${p.was.from}–${p.was.to} · ${esc(p.was.room)}`,
      ].join('\n'),
      rows: [[button('Open class', `v:${p.booking.id}`)]],
    };
  },

  cancelled(p, ctx) {
    const what = p.count > 1 ? `${p.count} classes, starting with:` : p.yours ? 'your class:' : 'a class:';
    return {
      text: `${esc(p.actor)} cancelled ${what}\n\n${classLines(p.booking, ctx.today)}`,
      rows: [[button('📅 That day', `s:${packDay(p.booking.day)}`)]],
    };
  },

  reminder(p, ctx) {
    return {
      text: `<b>Reminder</b> · ${leadTime(p.minutes)}\n\n${classLines(p.booking, ctx.today)}`,
      rows: [[button('Open class', `v:${p.booking.id}`)]],
    };
  },

  digest(p) {
    const lines = [`<b>Your classes today</b>, ${dayName(p.day)}`, ''];
    for (const b of p.classes) lines.push(`${b.from}–${b.to}  ${esc(b.class)} · ${esc(b.room)}`);
    return { text: lines.join('\n'), rows: [[button("📅 Today's schedule", 's')]] };
  },

  alert(p) {
    const lines = ['<b>The studio bot hit an error</b>', `Workflow: ${esc(p.workflow)}`];
    if (p.node) lines.push(`Step: ${esc(p.node)}`);
    lines.push('', esc(p.message));
    if (p.url) lines.push('', esc(p.url));
    return { text: lines.join('\n'), rows: [] };
  },
};

// ctx = the answer of studio.claim_due: { studio, today, messages }
function notifications(ctx) {
  return ctx.messages.map((message) => {
    const write = NOTIFICATIONS[message.kind];
    const view = write
      ? write(message.payload, ctx)
      : { text: `Studio bot: ${esc(message.kind)}`, rows: [] };
    const body = { chat_id: message.chat_id, text: view.text, parse_mode: 'HTML', disable_web_page_preview: true };
    if (view.rows.length) body.reply_markup = { inline_keyboard: view.rows };
    return { id: message.id, method: 'sendMessage', body };
  });
}

const due = $input.first().json.data;
return notifications(due).map((message) => ({ json: message }));

// One row per message: did Telegram take it? A message that failed stays in
// the outbox and is tried again by a later run.
const queued = $('Write notifications').all();
const results = $input.all().map((item, index) => ({
  id: queued[index].json.id,
  ok: item.json.ok === true,
  error: item.json.ok === true ? null : String(item.json.description ?? item.json.error?.message ?? item.json.error ?? 'send failed'),
}));
return [{ json: { results } }];
